// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): English 10, Unit 2, Rhetoric in Nonfiction.
// Our own wording and questions, written to the named national standards the course follows: the Common Core State
// Standards for English Language Arts, Reading: Informational Text, grades 9-10, and Writing. English 9 teaches these
// standards on short passages; English 10 goes deeper, so every skill here is a move in reading and writing ARGUMENT:
// how an author's ideas or claims are developed and refined by particular sentences, paragraphs and larger portions (RI.9-10.5),
// how an author's point of view or purpose is advanced by rhetoric (RI.9-10.6), delineating and evaluating an argument,
// valid reasoning, relevant and sufficient evidence, and fallacies (RI.9-10.8), how seminal U.S. documents address related
// themes (RI.9-10.9), and writing an argument with a precise claim, fair counterclaims and a conclusion that follows (W.9-10.1).
// RI.9-10.1 to 9-10.4 and 9-10.7 are met in English 9, and RI.9-10.10 by the variety of the passages. Five outline topics.
// Every real passage is public domain (a short clause or sentence, given with author, title and date, and checked against the
// text as commonly printed) or a paraphrase labelled "not a quotation"; the rest are labelled fictional and written for this
// unit. Nothing is reused from another language unit, and nothing is quoted from a copyrighted text. A question asks about the
// words on the page: the answer is in the passage or is a standard term of the course. Every question offers lettered choices
// in its prompt and takes the letter (or the choice's own words); the right letter moves around.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Video pictures: figure coordinates use a 100 x 34 sketch, north/up. Flow arrows trace before labels appear. */
const sketch=(title,regions,notes=[])=>{const pts={},polys=[];regions.forEach(([label,xy,col=0],i)=>{const v=xy.map(([x,y],k)=>{const n=String.fromCharCode(65+k)+i;pts[n]=[x,y];return n;}).join('');polys.push({v,label,col});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes:notes.map(([x,y,text])=>({at:[x,y],text})),dots:'',hide:Object.keys(pts).join('')};};
const flow=(title,stages)=>{const q=sketch(title,stages.map(([label],i)=>[label,[[i*36,13],[i*36+28,13],[i*36+28,25],[i*36,25]],i]),stages.map(([,detail],i)=>[i*36+14,7,detail]));q.segs=[];for(let i=0;i<2;i++){q.pts['P'+i]=[i*36+29,19];q.pts['Q'+i]=[i*36+35,19];q.segs.push({v:`P${i}Q${i}`,arrows:1,col:i,w:2});}q.hide=Object.keys(q.pts).join('');return q;};
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{})});
const pass=(title,texts,small=true)=>({t:'passages',title,texts,...(small?{small:true}:{})});
const L='ABCDEF';
/* lettered choices, the right one moved to position k: returns {text, letter} */
const dot=o=>o.replace(/\.$/,'');
const choose=(right,wrong,k)=>{right=dot(right);const opts=wrong.map(dot);opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(', '),letter:L[opts.indexOf(right)],n:opts.length};};
const ask=n=>n===2?'Answer A or B.':n===3?'Answer A, B or C.':`Answer ${[...L.slice(0,n-1)].join(', ')} or ${L[n-1]}.`;
const FIC='Fictional passage';
const MADISON='James Madison (usually credited), The Federalist No. 51 (1788)';
